var bar = new ArcAnnouncementBar
{
    Id = "fall-sale",
    Controls = true,
    AutoPlay = false,
    Messages = new[]
    {
        new ArcAnnouncement
        {
            Id = "sale",
            Message = "Fall sale: 30% off",
            Countdown = new ArcAnnouncementCountdown
            {
                To = DateTimeOffset.Now.AddDays(3),
                Label = "Ends in"
            },
            Action = new ArcAnnouncementAction { Label = "See plans" }
        },
        new ArcAnnouncement { Id = "beta", Message = "Workflows are now in beta" }
    }
};

bar.ActionInvoked += (_, message) => Track(message.Id);
